from subject import normalize_name


def test_normalize_name_collapses_whitespace_and_uses_hyphen():
    assert normalize_name(' Ada    Lovelace ') == 'ada-lovelace'

from subject import build_cache_key


def test_build_cache_key_keeps_one_separator():
    assert build_cache_key('video', '42') == 'video:42'

from subject import retry_delays


def test_retry_delays_are_exponential_from_one_second():
    assert retry_delays(3) == [1, 2, 4]

from subject import parse_headers


def test_parse_headers_strips_surrounding_spaces():
    assert parse_headers(' id, name ,created_at ') == ['id', 'name', 'created_at']

from subject import next_cursor


def test_next_cursor_is_none_for_an_empty_page():
    assert next_cursor([]) is None

from subject import merge_config


def test_override_wins_over_base_value():
    assert merge_config({'timeout': 10}, {'timeout': 30}) == {'timeout': 30}

from pathlib import Path


def resolve_project_path(root, relative):
    return Path(relative)

from subject import serialize_response


def test_serialize_response_keeps_payload_value():
    assert serialize_response({'id': 7}) == {'ok': True, 'data': {'id': 7}}

from subject import select_permission


def test_select_permission_returns_requested_when_allowed():
    assert select_permission('write', ['read', 'write']) == 'write'

from subject import normalize


def test_normalize_trims_value():
    assert normalize('  done  ') == 'done'

from subject import make_key


def test_make_key_keeps_namespace():
    assert make_key('user', '9') == 'user:9'

from subject import attempts


def test_attempts_are_one_based():
    assert attempts(3) == [1, 2, 3]
